from typing import List, Union

class LookupErr:
    def __init__(self, NotFound: str = "", EmptyCollection: bool = False):
        self.NotFound = NotFound
        self.EmptyCollection = EmptyCollection

    def __repr__(self):
        if self.EmptyCollection:
            return f"LookupErr(EmptyCollection=True)"
        return f"LookupErr(NotFound='{self.NotFound}')"

def safeFindRemove(arr: List[int], val: int) -> Union[List[int], LookupErr]:
    left = 0
    right = len(arr) - 1

    if len(arr) == 0:
        return LookupErr(EmptyCollection=True)

    if left <= right:
        if arr[left] == val:
            return arr[:left] + arr[left + 1:]
        else:
            left = left + 1
            if left <= right:
                if arr[left] == val:
                    return arr[:left] + arr[left + 1:]
                else:
                    left = left + 1
                    while left <= right:
                        if arr[left] == val:
                            return arr[:left] + arr[left + 1:]
                        left = left + 1

    return LookupErr(NotFound=f"Value {val} not found")

def main():
    test_cases = [
        ([1, 2, 3, 4, 5], 3),      # normal case, middle
        ([10, 20, 30], 10),        # first element
        ([7, 8, 9], 9),            # last element
        ([], 5),                   # empty array
        ([1, 2, 2, 3], 2),         # multiple occurrences, remove first
        ([100], 100),              # single element
        ([4, 5, 6], 99),           # not found
        ([0, 0, 0], 0),            # all same values
        ([-1, -2, -3], -2),        # negative values
        ([1, 2, 3, 4, 5], 1),      # first of many
    ]

    for arr, val in test_cases:
        result = safeFindRemove(arr, val)
        print(result)

if __name__ == "__main__":
    main()

