import java.util.Arrays;

public class Solution {
    public static class LookupErr {
        public final String NotFound;
        public final Boolean EmptyCollection;

        private LookupErr(String notFound, Boolean emptyCollection) {
            this.NotFound = notFound;
            this.EmptyCollection = emptyCollection;
        }

        public static LookupErr notFound(String msg) {
            return new LookupErr(msg, null);
        }

        public static LookupErr emptyCollection() {
            return new LookupErr(null, true);
        }

        @Override
        public String toString() {
            if (NotFound != null) return "NotFound: " + NotFound;
            if (EmptyCollection != null) return "EmptyCollection: true";
            return "LookupErr";
        }
    }

    public static Object[] safeFindRemove(int[] arr, int val) {
        if (arr.length == 0) {
            return new Object[]{null, LookupErr.emptyCollection()};
        }

        int index = -1;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == val) {
                index = i;
                break;
            }
        }

        if (index == -1) {
            return new Object[]{null, LookupErr.notFound("Value " + val + " not found")};
        }

        int[] result = new int[arr.length - 1];
        int left = 0;
        int right = 0;

        while (right < arr.length) {
            if (right == index) {
                right++;
                continue;
            }
            result[left] = arr[right];
            left++;
            right++;
        }

        return new Object[]{result, null};
    }

